cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// 1. Generate a unique reservation ID (like the tool does: HATHAT, HATHAU, HATHAV)
const existingIds = db.prepare(\"SELECT booking_id FROM flight_bookings WHERE source_skill = 'tau2Airline'\").all().map(r => r.booking_id);
let reservationId = null;
for (const candidate of ['HATHAT', 'HATHAU', 'HATHAV']) {
  if (!existingIds.includes(candidate)) {
    reservationId = candidate;
    break;
  }
}
if (!reservationId) throw new Error('Could not generate reservation ID');
console.log('Reservation ID:', reservationId);

// 2. Flight details
const flightNumber = 'FLD3D594';
const date = '2026-09-10';
const cabin = 'economy';
const price = 129;

// 3. Update available seats (decrement economy by 1)
const flight = db.prepare(\"SELECT * FROM flights WHERE flight_id = ?\").get(flightNumber);
const datesJson = JSON.parse(flight.dates_json);
datesJson[date].available_seats.economy -= 1;
db.prepare(\"UPDATE flights SET dates_json = ? WHERE flight_id = ? AND source_skill = 'tau2Airline'\")
  .run(JSON.stringify(datesJson), flightNumber);
console.log('Updated seats - economy now:', datesJson[date].available_seats.economy);

// 4. Insert the reservation
const flightsJson = JSON.stringify([{
  flight_id: flightNumber,
  origin: 'LAX',
  destination: 'SFO',
  date: date,
  price: price
}]);

const passengersJson = JSON.stringify([{
  first_name: 'Maya',
  last_name: 'Chen',
  dob: '1991-04-18'
}]);

const paymentHistoryJson = JSON.stringify([{
  payment_id: 'cc_2402ef91',
  amount: 129
}]);

const createdAt = '2024-05-15T15:00:00';

db.prepare(
  'INSERT INTO flight_bookings (booking_id, user_id, origin, destination, ' +
  'flight_type, cabin_class, flights_json, passengers_json, payment_history_json, ' +
  'booked_at, total_baggages, nonfree_baggages, add_insurance, status, source_skill) ' +
  'VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)'
).run(
  reservationId,
  'user_fa209a3f',
  'LAX',
  'SFO',
  'one_way',
  cabin,
  flightsJson,
  passengersJson,
  paymentHistoryJson,
  createdAt,
  0,    // total_baggages
  0,    // nonfree_baggages
  'no', // insurance
  'confirmed',
  'tau2Airline'
);

console.log('Reservation inserted successfully!');

// 5. Verify the booking
const booking = db.prepare(\"SELECT * FROM flight_bookings WHERE booking_id = ?\").get(reservationId);
console.log('\nBooking confirmation:');
console.log(JSON.stringify(booking, null, 2));
"
